{"witnessCode": "import { describe, it } from 'node:test';
import { strict as assert } from 'node:assert/strict';
import normalizeUrl from '../index.js';

describe('keepQueryParameters empty array regression', () => {
  it('should keep query parameters when keepQueryParameters is empty array', () => {
    const url = 'https://example.com/path?foo=1&bar=2';
    const options = {
      keepQueryParameters: [],
      removeQueryParameters: [],
      sortQueryParameters: false,
    };
    const expected = 'https://example.com/path?foo=1&bar=2';
    const actual = normalizeUrl(url, options);
    assert.strictEqual(actual, expected);
  });
});"}
